CREATE OR REPLACE FUNCTION public.icash_claim_before_activation(p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare b public.icash_operating_budget; o public.icash_operation_spend; r public.icash_operation_rates; a public.icash_accounts;
begin
 select * into b from public.icash_operating_budget where id=1 for update;
 select * into o from public.icash_operation_spend where operation_key=p_operation for update;
 if not found or o.state<>'reserved' or not b.enabled or (b.require_company_reserve and b.funded_micros::numeric-b.spent_micros-b.protected_micros<b.reserved_micros) then return false; end if;
 select * into a from public.icash_accounts where id=o.account_id for update;
 select * into r from public.icash_operation_rates where id=o.rate_id for share;
 if exists(select 1 from public.icash_voice_jobs j where j.account_id=o.account_id and 'voice:'||j.id=p_operation
  and j.meta_followup_lead_id is not null and not public.icash_meta_followup_current(j.meta_followup_lead_id,'call'))
 or exists(select 1 from public.icash_meta_lead_messages mm join public.icash_text_messages msg on msg.id=mm.message_id
  where msg.account_id=o.account_id and 'text:'||msg.id=p_operation and mm.purpose in ('followup_1','followup_2')
  and not public.icash_meta_followup_current(mm.lead_id,mm.purpose)) then return false;end if;

 if (a.bot_paused and not public.icash_general_reception_pause_exempt(o.account_id,p_operation,o.charge_cap_cents) and not public.icash_customer_text_operation(o.account_id,p_operation)) or not r.enabled or r.expires_at<=now() or o.permission_until<=now() then return false; end if;
 if r.operation='seller_call' and not public.icash_limited_seller_voice(o.account_id,p_operation) and not public.icash_cancellation_voice_current(o.account_id,p_operation) and not exists(select 1 from public.icash_voice_jobs meta_job where meta_job.account_id=o.account_id and 'voice:'||meta_job.id=p_operation and public.icash_meta_voice_context(o.account_id,meta_job.id) is not null) and (o.financial_checked_at is null or o.financial_checked_at<now()-interval '24 hours') then return false; end if;
 update public.icash_operation_spend set state='dispatched',dispatched_at=now() where operation_key=p_operation;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_before_membership(p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a uuid;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 if exists(select 1 from public.icash_operating_budget where id=1 and not require_company_reserve) then
 select account_id into a from public.icash_operation_spend where operation_key=p_operation;
 if not exists(select 1 from public.icash_spend_activations where account_id=a and enabled) then return false;end if;
 end if;
 return public.icash_claim_before_activation(p_operation);
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_before_seller_response(p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a uuid;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select account_id into a from public.icash_operation_spend where operation_key=p_operation;
 if not public.icash_membership_work_allowed(a) then return false;end if;
 perform 1 from public.icash_wallets where account_id=a and balance_cents>0 for update;
 if not found then return false;end if;
 return public.icash_claim_before_membership(p_operation);
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_cold_inventory(p_account uuid, p_screening uuid, p_phone text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare prop text;keys text[];k text;held public.icash_inventory_claims;contact text;
begin
 select snapshot->>'propertyId' into prop from public.icash_screening_jobs where id=p_screening and account_id=p_account;
 if prop is null or prop !~ '^prop_[A-Za-z0-9]+$' then return false;end if;
 if exists(select 1 from public.icash_outbound_property_owners where property_id=prop and account_id<>p_account) then return false;end if;
 keys:=array['property:'||prop];
 if p_phone is not null then
 if p_phone !~ '^[+][1-9][0-9]{7,14}$' then return false;end if;
 contact:=encode(extensions.digest(p_phone,'sha256'),'hex');
 if exists(select 1 from public.icash_text_suppressions where phone=p_phone) or exists(select 1 from public.icash_contact_suppressions where contact_key=contact) then return false;end if;
 keys:=array_append(keys,'phone:'||contact);
 end if;
 -- All callers share deterministic lock ordering. No partial claim on a denied pair.
 for k in select x from unnest(keys) x order by x loop perform pg_advisory_xact_lock(hashtextextended(k,219));end loop;
 for k in select x from unnest(keys) x order by x loop
 select * into held from public.icash_inventory_claims where resource_key=k;
 if found and held.account_id<>p_account and (
 held.cooldown_until>now()
 or exists(select 1 from public.icash_deal_files d join public.icash_screening_jobs s on s.id=d.screening_id where d.account_id=held.account_id and d.stage in ('under_contract','buyer_selected','title_open','closing') and s.snapshot->>'propertyId'=(select snapshot->>'propertyId' from public.icash_screening_jobs where id=held.screening_id))
 or exists(select 1 from public.icash_live_callbacks where account_id=held.account_id and screening_id=held.screening_id and state in ('pending_dispatch_review','held_for_human'))
 or exists(select 1 from public.icash_live_conversations where account_id=held.account_id and screening_id=held.screening_id and state in ('waiting','review'))
 ) then return false;end if;
 end loop;
 foreach k in array keys loop
 insert into public.icash_inventory_claims(resource_key,account_id,screening_id,cooldown_until) values(k,p_account,p_screening,now()+interval '30 days')
 on conflict(resource_key) do update set account_id=excluded.account_id,screening_id=excluded.screening_id,cooldown_until=excluded.cooldown_until,updated_at=now();
 end loop;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_operation(p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a uuid;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select account_id into a from public.icash_operation_spend where operation_key=p_operation;
 if a is not null and not public.icash_seller_response_operation_allowed(a,p_operation) then return false;end if;
 if a is not null and not public.icash_seller_text_operation_current(a,p_operation) then return false;end if;
 return public.icash_claim_before_seller_response(p_operation);
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_owner_before_recovery_cap(p_account uuid, p_screening uuid, p_operation text, p_snapshot jsonb, p_rate uuid, p_credit_cap integer, p_unit_cost_micros bigint, p_quoted_data_cost_micros bigint, p_rights_until timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 o public.icash_operation_spend;
 s public.icash_screening_jobs;
 c public.icash_discovery_configs;
 r public.icash_operation_rates;
 prop text;manual_hold boolean;fetched timestamptz;checked_at timestamptz;
begin
 if p_account is null or p_screening is null or p_operation is distinct from 'owners:'||p_account||':'||p_screening
  or jsonb_typeof(p_snapshot) is distinct from 'object' or p_rate is null
  or p_credit_cap is null or p_credit_cap not between 1 and 25
  or p_unit_cost_micros is null or p_unit_cost_micros not between 1 and 9007199254740991
  or p_quoted_data_cost_micros is null or p_quoted_data_cost_micros not between 1 and 9007199254740991
  or p_credit_cap::numeric*p_unit_cost_micros>p_quoted_data_cost_micros or p_rights_until is null then return false;end if;
 -- Match the underlying claim's budget -> operation -> account order. Existing
 -- takeover paths lock the account (and current wrappers lock budget first).
 perform 1 from public.icash_operating_budget where id=1 for update;
 if not found then return false;end if;
 select * into o from public.icash_operation_spend where operation_key=p_operation for update;
 if not found or o.account_id is distinct from p_account or o.rate_id is distinct from p_rate or o.state<>'reserved' or o.permission_until is distinct from p_rights_until then return false;end if;
 perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;
 if not found then return false;end if;
 select * into s from public.icash_screening_jobs where id=p_screening and account_id=p_account for share;
 if not found or s.state<>'complete' or s.snapshot ? 'sellerRequest' or s.snapshot is distinct from p_snapshot or s.result->'financialCheck'->>'status' is distinct from 'eligible' then return false;end if;
 prop:=s.snapshot->>'propertyId';
 if prop is null or prop !~ '^prop_[0-9]{1,20}$' or s.snapshot->'raw'->'data'->>'dm_property_id' is distinct from prop or s.snapshot->>'propertyType' is distinct from 'house' then return false;end if;
 -- Inventory rotation can already hold config before its scheduler takes budget.
 -- Fail closed instead of waiting for that row while this claim holds budget.
 begin
  select * into c from public.icash_discovery_configs where account_id=p_account for share nowait;
 exception when lock_not_available then return false;end;
 if not found or not c.enabled or not c.contacts_enabled or c.contact_rate_id is distinct from p_rate
  or c.contact_credit_cap is distinct from p_credit_cap or c.property_credit_micros is distinct from p_unit_cost_micros
  or c.data_rights_until is distinct from p_rights_until then return false;end if;
 select * into r from public.icash_operation_rates where id=p_rate for share;
 if not found or not r.enabled or r.operation<>'owner_enrichment'
  or jsonb_typeof(r.costs_micros->'dealmachine') is distinct from 'number'
  or (r.costs_micros->>'dealmachine')::numeric is distinct from p_quoted_data_cost_micros::numeric then return false;end if;
 -- A locked row must exist even for a property's first lookup. Do not change an
 -- existing manual choice. This also serializes direct property-control upserts.
 insert into public.icash_property_controls(account_id,property_id,manual) values(p_account,prop,false) on conflict do nothing;
 select manual into manual_hold from public.icash_property_controls where account_id=p_account and property_id=prop for update;
 if not found or manual_hold then return false;end if;
 begin fetched:=(s.snapshot->>'fetchedAt')::timestamptz;
 exception when invalid_datetime_format or datetime_field_overflow then return false;end;
 -- Use wall clock after waiting for all locks, rather than transaction-start time.
 checked_at:=clock_timestamp();
 if fetched is null or fetched<checked_at-interval '24 hours' or fetched>checked_at
  or s.completed_at is null or s.completed_at<checked_at-interval '24 hours' or s.completed_at>checked_at
  or c.data_rights_until<=checked_at or r.expires_at<=checked_at or r.verified_at>checked_at
  or o.permission_until<=checked_at then return false;end if;
 -- No weakened or copied billing implementation: activation, pause, funds, rate,
 -- reservation state and exactly-once checks remain in the existing dispatcher.
 if not public.icash_research_purchase_allowed(p_account,p_operation,p_rate) then return false;end if; return public.icash_claim_operation(p_operation);
end $function$

CREATE OR REPLACE FUNCTION public.icash_cold_inventory_available(p_account uuid, p_screening uuid, p_phone text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare prop text;keys text[];contact text;
begin
 select snapshot->>'propertyId' into prop from public.icash_screening_jobs where id=p_screening and account_id=p_account;
 if prop is null or prop !~ '^prop_[A-Za-z0-9]+$' then return false;end if;
 if exists(select 1 from public.icash_outbound_property_owners where property_id=prop and account_id<>p_account) then return false;end if;
 keys:=array['property:'||prop];
 if p_phone is not null then
  if p_phone !~ '^[+][1-9][0-9]{7,14}$' then return false;end if;
  contact:=encode(sha256(convert_to(p_phone,'UTF8')),'hex');
  if exists(select 1 from public.icash_text_suppressions where phone=p_phone)
   or exists(select 1 from public.icash_contact_suppressions where contact_key=contact) then return false;end if;
  keys:=array_append(keys,'phone:'||contact);
 end if;
 return not exists(select 1 from public.icash_inventory_claims held where held.resource_key=any(keys) and held.account_id<>p_account and (
  held.cooldown_until>now()
  or exists(select 1 from public.icash_deal_files d join public.icash_screening_jobs s on s.id=d.screening_id
   where d.account_id=held.account_id and d.stage in ('under_contract','buyer_selected','title_open','closing')
    and s.snapshot->>'propertyId'=(select snapshot->>'propertyId' from public.icash_screening_jobs where id=held.screening_id))
  or exists(select 1 from public.icash_live_callbacks where account_id=held.account_id and screening_id=held.screening_id and state in ('pending_dispatch_review','held_for_human'))
  or exists(select 1 from public.icash_live_conversations where account_id=held.account_id and screening_id=held.screening_id and state in ('waiting','review'))
 ));
end $function$

CREATE OR REPLACE FUNCTION public.icash_guard_prospecting_spend()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare kind text;required bigint;
begin
 if not public.icash_new_prospect_operation(new.account_id,new.operation_key,new.rate_id) then return new;end if;
 perform 1 from public.icash_operating_budget where id=1 for update;
 select operation into kind from public.icash_operation_rates where id=new.rate_id;
 required:=new.charge_cap_cents;
 if kind in ('property_search','owner_enrichment') then
  required:=public.icash_research_admission_quote(new.account_id,kind,required);
  if icash_work_private.warm_seller_due(new.account_id) or public.icash_research_waiting_on_outreach(new.account_id) then
   raise exception 'Prospecting budget reached' using detail=jsonb_build_object('quoteCents',required)::text;
  end if;
 elsif kind='contact_revalidation' then
  required:=public.icash_research_admission_quote(new.account_id,kind,required);
 elsif kind in ('sms_send','mms_send') and public.icash_research_waiting_on_outreach(new.account_id) then
  required:=required+public.icash_prospecting_outreach_floor(new.account_id);
 end if;
 if public.icash_prospecting_available(new.account_id)<required then
  raise exception 'Prospecting budget reached' using detail=jsonb_build_object('quoteCents',required)::text;
 end if;
 select id into new.prospecting_budget_id from public.icash_prospecting_budgets where account_id=new.account_id order by id desc limit 1;
 if new.prospecting_budget_id is null then raise exception 'Prospecting budget reached' using detail=jsonb_build_object('quoteCents',required)::text;end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_prospecting_outreach_floor(p_account uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare r public.icash_operation_rates;b public.icash_operating_budget;parts jsonb;total numeric;
begin
 if not public.icash_outreach_voice_current(p_account) then return 0;end if;
 select rate.* into r from public.icash_voice_configs c join public.icash_operation_rates rate on rate.id=c.seller_rate_id
  where c.account_id=p_account and c.enabled and c.reviewed_until>now() and rate.enabled
   and rate.verified_at<=now() and rate.expires_at>now() and rate.operation='seller_call'
   and rate.voice_max_duration_seconds=600 and rate.charge_cents=977 and rate.version like 'required-audio-30d-speech-v1:%';
 if not found then return 0;end if;
 select * into b from public.icash_operating_budget where id=1;
 if public.icash_vip_active(p_account) then b.standard_cost_multiplier:=b.standard_cost_multiplier*0.7;b.elevenlabs_cost_multiplier:=b.elevenlabs_cost_multiplier*0.7;end if;
 parts:=public.icash_voice_bounded_costs(r.costs_micros,120);
 select sum(value::numeric) into total from jsonb_each_text(parts);
 return greatest(0,ceil((total*b.standard_cost_multiplier-(parts->>'elevenlabs')::numeric*(b.standard_cost_multiplier-b.elevenlabs_cost_multiplier))*(10000+r.buffer_bps)/100000000))::bigint;
end $function$

CREATE OR REPLACE FUNCTION public.icash_research_purchase_allowed(p_account uuid, p_operation text, p_rate uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
 declare r public.icash_operation_rates;a public.icash_accounts;p public.icash_acquisition_policy;spent bigint;screen public.icash_screening_jobs;
 begin
  select * into r from public.icash_operation_rates where id=p_rate;
  if not found then return false;end if;
  if r.operation not in ('property_search','owner_enrichment') then return true;end if;
  select * into p from public.icash_acquisition_policy where id=1;
  if not found or p.mode='inbound' then return false;end if;
  select * into a from public.icash_accounts where id=p_account;
  if not found or a.bot_paused or not exists(select 1 from public.icash_wallets where account_id=p_account and balance_cents>0) then return false;end if;
  if r.operation='owner_enrichment' then
   select * into screen from public.icash_screening_jobs where account_id=p_account and 'owners:'||p_account||':'||id=p_operation;
   if not found or screen.snapshot->'sellerRequest' is not null or not public.icash_research_state_allowed(screen.snapshot->'raw'->'data'->>'state') then return false;end if;
   if exists(select 1 from public.icash_outbound_property_owners where property_id=screen.snapshot->>'propertyId' and account_id<>p_account) then return false;end if;
  elsif not exists(select 1 from public.icash_discovery_configs where account_id=p_account and public.icash_research_zip_known(zip)) then return false;
  end if;
  return true;
 end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_before_activation(p_account uuid, p_operation text, p_rate uuid, p_permission_until timestamp with time zone, p_financial_checked_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_financial_eligible boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare op text;screen uuid;phone text;party text;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select operation into op from public.icash_operation_rates where id=p_rate;
 if op='owner_enrichment' then
 select id into screen from public.icash_screening_jobs where account_id=p_account and 'owners:'||p_account||':'||id=p_operation;
 elsif op='seller_call' then
 select p.screening_id,p.phone into screen,phone
 from public.icash_voice_jobs j
 join public.icash_voice_contact_targets p on p.id=coalesce(j.permission_id,j.operational_contact_id) and p.account_id=j.account_id
 where j.account_id=p_account and 'voice:'||j.id=p_operation and p.party='seller'
 and (j.permission_id is null)<>(j.operational_contact_id is null)
 and ((j.permission_id is not null and p.eligibility_source='operator_record')
  or (j.operational_contact_id is not null and p.eligibility_source='operational_checks_only'
   and public.icash_operational_contact_current(p_account,j.operational_contact_id,'voice',false)));
 elsif op in ('sms_send','mms_send') then
 select d.screening_id,t.recipient,t.party into screen,phone,party from public.icash_text_messages m join public.icash_text_threads t on t.id=m.thread_id and t.account_id=m.account_id join public.icash_deal_files d on d.id=t.deal_id and d.account_id=t.account_id where m.account_id=p_account and 'text:'||m.id=p_operation;
 end if;
 if op in ('owner_enrichment','seller_call') or (op in ('sms_send','mms_send') and party='seller') then
 if screen is null or (not public.icash_meta_contact_only(p_account,screen,phone) and not public.icash_claim_inventory(p_account,screen,phone)) then raise exception 'Seller inventory assigned or suppressed';end if;
 end if;
 return public.icash_reserve_before_inventory(p_account,p_operation,p_rate,p_permission_until,p_financial_checked_at,p_financial_eligible);
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_before_fractional(p_account uuid, p_operation text, p_rate uuid, p_permission_until timestamp with time zone, p_financial_checked_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_financial_eligible boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare b public.icash_operating_budget; r public.icash_operation_rates; o public.icash_operation_spend; cat text; n numeric; total numeric:=0; held bigint; daily numeric; cr uuid; required numeric; price numeric; dm_mult numeric; data_unit bigint; data_basis text;
begin
 if p_operation is null or length(p_operation) not between 1 and 160 then raise exception 'Invalid operation'; end if;
 select * into b from public.icash_operating_budget where id=1 for update;
 if not b.enabled then raise exception 'Automation on hold'; end if;
 select * into o from public.icash_operation_spend where operation_key=p_operation;
 if found then
  if o.account_id<>p_account or o.rate_id<>p_rate then raise exception 'Operation conflict'; end if;
  return jsonb_build_object('operationKey',o.operation_key,'state',o.state,'reservedMicros',o.reserved_micros);
 end if;
 select * into r from public.icash_operation_rates where id=p_rate for share;
 if not found or not r.enabled or r.verified_at>now() or r.expires_at<=now() then raise exception 'Verified rate required'; end if;
 if public.icash_voice_credit_bound(p_account,p_operation,p_rate) is not null then
  r.charge_cents:=(public.icash_voice_credit_bound(p_account,p_operation,p_rate)->>'charge_cents')::bigint;
  r.costs_micros:=public.icash_voice_credit_bound(p_account,p_operation,p_rate)->'costs_micros';
 end if;
 if public.icash_reception_credit_bound(p_account,p_operation,p_rate) is not null then
  r.charge_cents:=(public.icash_reception_credit_bound(p_account,p_operation,p_rate)->>'charge_cents')::bigint;
  r.costs_micros:=public.icash_reception_credit_bound(p_account,p_operation,p_rate)->'costs_micros';
 end if;
 if p_permission_until is null or p_permission_until<=now() then raise exception 'Permission expired'; end if;
 if r.operation='seller_call' and not public.icash_limited_seller_voice(p_account,p_operation) and not public.icash_cancellation_voice_current(p_account,p_operation) and not exists(select 1 from public.icash_voice_jobs meta_job where meta_job.account_id=p_account and 'voice:'||meta_job.id=p_operation and public.icash_meta_voice_context(p_account,meta_job.id) is not null) and (p_financial_eligible is distinct from true or p_financial_checked_at is null or p_financial_checked_at>now() or p_financial_checked_at<now()-interval '24 hours') then raise exception 'Financial screening required'; end if;
 foreach cat in array array['dealmachine','elevenlabs','twilio','messaging','email','llm','vercel','railway','supabase','github','payments','title_and_signing','support_and_overhead','acquisition','refund_and_dispute_reserve','other'] loop
  if jsonb_typeof(r.costs_micros->cat) is distinct from 'number' then raise exception 'Unknown cost: %',cat; end if;
  n:=(r.costs_micros->>cat)::numeric;
  if n<0 or n<>trunc(n) or n>9007199254740991 then raise exception 'Invalid cost'; end if;
  total:=total+n;
 end loop;
 if public.icash_vip_active(p_account) then b.standard_cost_multiplier:=b.standard_cost_multiplier*0.7;b.elevenlabs_cost_multiplier:=b.elevenlabs_cost_multiplier*0.7;end if;
 if r.operation='seller_lead' then
  b.standard_cost_multiplier:=public.icash_seller_lead_rate_multiplier(p_account,p_operation,p_rate)*case when public.icash_vip_active(p_account) then 0.7 else 1 end;
  b.elevenlabs_cost_multiplier:=b.standard_cost_multiplier;
 end if;
 if r.operation in ('property_search','owner_enrichment','buyer_discovery','contact_revalidation') then
  dm_mult:=3*case when public.icash_vip_active(p_account) then 0.7 else 1 end;
  select credit_micros,cost_basis into strict data_unit,data_basis from public.icash_data_cost_settings where provider='dealmachine';
 end if;
 -- Match JS: round reserve up to a cent after adding buffer.
 held:=ceil(total*(10000+r.buffer_bps)/10000);
 required:=ceil((total*b.standard_cost_multiplier-(r.costs_micros->>'elevenlabs')::numeric*(b.standard_cost_multiplier-b.elevenlabs_cost_multiplier)+coalesce((r.costs_micros->>'dealmachine')::numeric*(dm_mult-b.standard_cost_multiplier),0))*(10000+r.buffer_bps)/10000);
 price:=r.charge_cents::numeric*10000;
 if r.operation='sms_send' then
 select customer_price_micros into price from public.icash_text_messages where 'text:'||id=p_operation and account_id=p_account;
 end if;

 if r.flat_customer_price_cents is not null then
  if r.operation<>'sms_send' or price is distinct from r.flat_customer_price_cents::numeric*10000 then raise exception 'SMS flat price snapshot mismatch';end if;
  -- Snapshot cost-coverage accounting only for this explicit flat-price operation.
  -- The existing fractional ledger charges the immutable customer_price_micros.
  required:=held;b.standard_cost_multiplier:=1;b.elevenlabs_cost_multiplier:=1;
 end if;
 if price is null or price<required then raise exception 'Price below provider cost multiplier';end if;
 if b.require_company_reserve and b.funded_micros::numeric-b.spent_micros-b.reserved_micros-b.protected_micros<held then raise exception 'Company budget exhausted'; end if;
 select coalesce(sum(actual_micros),0) into daily from public.icash_operation_spend where settled_at>now()-interval '24 hours';
 if b.require_company_reserve and daily+b.reserved_micros+held>b.daily_limit_micros then raise exception 'Company daily limit'; end if;
 cr:=public.icash_reserve_credit(p_account,p_operation,r.charge_cents);
 insert into public.icash_operation_spend(operation_key,account_id,rate_id,credit_reservation_id,charge_cap_cents,reserved_micros,permission_until,financial_checked_at)
 values(p_operation,p_account,p_rate,cr,r.charge_cents,held,p_permission_until,p_financial_checked_at);
 update public.icash_operation_spend set standard_cost_multiplier=b.standard_cost_multiplier,elevenlabs_cost_multiplier=b.elevenlabs_cost_multiplier,required_revenue_micros=required,dealmachine_cost_multiplier=dm_mult,data_unit_cost_micros=data_unit,data_cost_basis=data_basis where operation_key=p_operation;
 update public.icash_operating_budget set reserved_micros=reserved_micros+held where id=1;
 return jsonb_build_object('operationKey',p_operation,'state','reserved','reservedMicros',held);
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_before_inventory(p_account uuid, p_operation text, p_rate uuid, p_permission_until timestamp with time zone, p_financial_checked_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_financial_eligible boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare price bigint;r public.icash_operation_rates;result jsonb;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into r from public.icash_operation_rates where id=p_rate;
 if r.operation='sms_send' then
 select m.customer_price_micros into price from public.icash_text_messages m where 'text:'||m.id=p_operation and m.account_id=p_account and m.direction='outgoing' and cardinality(m.asset_ids)=0;
 if price is null then raise exception 'SMS customer price missing';end if;
 if r.charge_cents<ceil(price::numeric/10000) then raise exception 'SMS credit reservation insufficient';end if;
 end if;
 result:=public.icash_reserve_before_fractional(p_account,p_operation,p_rate,p_permission_until,p_financial_checked_at,p_financial_eligible);
 if price is not null then
 update public.icash_operation_spend set customer_price_micros=price where operation_key=p_operation and customer_price_micros is null;
 if exists(select 1 from public.icash_operation_spend where operation_key=p_operation and customer_price_micros<>price) then raise exception 'SMS price changed after reservation';end if;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_before_membership(p_account uuid, p_operation text, p_rate uuid, p_permission_until timestamp with time zone, p_financial_checked_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_financial_eligible boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare cap bigint;used numeric;charge bigint;b public.icash_operating_budget;
begin
 select * into b from public.icash_operating_budget where id=1 for update;
 if not b.require_company_reserve then
 select customer_cap_cents into cap from public.icash_spend_activations where account_id=p_account and enabled;
 if cap is null or not exists(select 1 from public.icash_funding_orders where account_id=p_account and mode='live' and state='paid' and credited_at is not null) then raise exception 'Account spending not activated';end if;
 -- A paid, enabled account spends its current balance; no lifetime spending cap.
 end if;
 return public.icash_reserve_before_activation(p_account,p_operation,p_rate,p_permission_until,p_financial_checked_at,p_financial_eligible);
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_before_vip(p_account uuid, p_operation text, p_rate uuid, p_permission_until timestamp with time zone, p_financial_checked_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_financial_eligible boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 if not exists(select 1 from public.icash_operation_spend where operation_key=p_operation) and not public.icash_research_purchase_allowed(p_account,p_operation,p_rate) then raise exception 'Research pacing or state hold';end if;
 if not public.icash_membership_work_allowed(p_account) then raise exception 'Software membership is inactive';end if;
 return public.icash_reserve_before_membership(p_account,p_operation,p_rate,p_permission_until,p_financial_checked_at,p_financial_eligible);
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_credit_before_owner_recovery(p_account uuid, p_operation text, p_amount bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w public.icash_wallets; r public.icash_credit_reservations; a public.icash_accounts; used bigint; result uuid; allowance jsonb;
begin
 if p_operation is null or trim(p_operation)='' or p_amount is null or p_amount<=0 then raise exception 'Invalid reservation'; end if;
 select * into a from public.icash_accounts where id=p_account for update;
 if not found then raise exception 'Account missing'; end if;
 if not public.icash_membership_work_allowed(p_account) then raise exception 'Software membership is inactive';end if;
 select * into w from public.icash_wallets where account_id=p_account for update;
 if not found then raise exception 'Wallet missing'; end if;
 select * into r from public.icash_credit_reservations where operation_key=p_operation;
 if found then
  if r.account_id<>p_account or r.amount_cents<>p_amount then raise exception 'Idempotency conflict'; end if;
  if r.status<>'reserved' then raise exception 'Operation already resolved'; end if;
  if a.bot_paused and not public.icash_general_reception_pause_exempt(p_account,p_operation,p_amount) and not public.icash_customer_text_operation(p_account,p_operation) and not exists(select 1 from public.icash_question_usage q where q.account_id=p_account and 'question:'||q.question_id=p_operation and q.state='reserved' and p_amount=5) then raise exception 'Bot paused'; end if;
  return r.id;
 end if;
 if a.bot_paused and not public.icash_general_reception_pause_exempt(p_account,p_operation,p_amount) and not public.icash_customer_text_operation(p_account,p_operation) and not exists(select 1 from public.icash_question_usage q where q.account_id=p_account and 'question:'||q.question_id=p_operation and q.state='reserved' and p_amount=5) then raise exception 'Bot paused'; end if;
 if w.balance_cents<=0 then raise exception 'Insufficient credits'; end if;
 -- This row is an idempotent usage authorization, not a wallet hold.
 -- The work planner chooses affordable work; actual usage is deducted once.
 insert into public.icash_credit_reservations(account_id,operation_key,amount_cents)
 values(p_account,p_operation,p_amount) returning id into result;

 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_operation(p_account uuid, p_operation text, p_rate uuid, p_permission_until timestamp with time zone, p_financial_checked_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_financial_eligible boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result jsonb;existed boolean; prior public.icash_operation_spend;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into prior from public.icash_operation_spend where operation_key=p_operation;existed:=found;
 if existed then
  if prior.account_id<>p_account or prior.rate_id<>p_rate or not public.icash_membership_work_allowed(p_account) then raise exception 'Operation conflict';end if;
  return jsonb_build_object('operationKey',prior.operation_key,'state',prior.state,'reservedMicros',prior.reserved_micros);
 end if;
 result:=public.icash_reserve_before_vip(p_account,p_operation,p_rate,p_permission_until,p_financial_checked_at,p_financial_eligible);
 if not existed and public.icash_vip_active(p_account) then
  -- Flat SMS is already an explicit retail price; apply the 30% usage reduction
  -- to the operation snapshot only. No re-pricing after dispatch or on retries.
  update public.icash_operation_spend set customer_price_micros=ceil(customer_price_micros::numeric*0.7)
   where operation_key=p_operation and customer_price_micros is not null;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.icash_seller_contact_evidence(p_account uuid, p_screening uuid, p_lead uuid, p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare m public.icash_meta_leads;l public.icash_seller_intakes;principal text;binding jsonb;
begin
 select ml.* into m from public.icash_meta_leads ml join public.icash_meta_lead_sources src on src.id=ml.source_id where ml.lead_id=p_lead and src.routing_mode='network_pool';
 if not found then return public.icash_meta_direct_contact_evidence(p_account,p_screening,p_lead,p_phone);end if;
 select * into l from public.icash_seller_intakes where id=p_lead;
 if l.phone is distinct from p_phone or not public.icash_meta_pool_receipt_current(p_lead)
 or ((m.account_id=p_account and m.screening_id=p_screening and l.assigned_account=p_account and l.screening_id=p_screening)
  or exists(select 1 from public.icash_seller_matches sm where sm.lead_id=p_lead and sm.account_id=p_account and sm.screening_id=p_screening)) is not true
 or exists(select 1 from public.icash_handoffs where account_id=p_account and screening_id=p_screening and state<>'resolved') then return null;end if;
 select i.principal into principal from public.icash_customer_identities i where i.account_id=p_account;
 if nullif(trim(principal),'') is null then return null;end if;
 binding:=jsonb_build_object('lead',l.id,'account',p_account,'screening',p_screening,'phone',p_phone,'principal',principal,'metaLeadId',m.meta_id,'formId',m.form_id,'consent',m.consent_receipt,'consentVersion',m.consent_version,'consentText',m.consent_text,'scope',l.contact_consent_scope,'sharing',l.sharing_text,'submittedAt',m.submitted_at,'timezone',m.timezone);
 return jsonb_build_object('timezone',m.timezone,'until',m.contact_until,'evidence','meta-network:'||l.id||':'||encode(sha256(convert_to(binding::text,'UTF8')),'hex'));
end $function$

CREATE OR REPLACE FUNCTION public.icash_seller_phone_call_current(p_account uuid, p_job uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_voice_jobs;p public.icash_voice_contact_targets;n bigint;last_attempt timestamptz;unknown_attempt boolean;
begin
 select * into j from public.icash_voice_jobs where id=p_job and account_id=p_account;
 if not found then return false;end if;
 select * into p from public.icash_voice_contact_targets
 where id=coalesce(j.permission_id,j.operational_contact_id) and account_id=p_account and party='seller'
 and ((j.permission_id is not null and j.operational_contact_id is null and eligibility_source='operator_record')
  or (j.permission_id is null and j.operational_contact_id is not null and eligibility_source='operational_checks_only'));
 if not found or p.phone is null or p.phone !~ '^\+[1-9][0-9]{7,14}$' then return false;end if;
 if exists(select 1 from public.icash_call_recordings r where r.voice_job_id=p_job
  and (r.account_id is distinct from p_account or r.to_phone is distinct from p.phone)) then return false;end if;
 select count(*),max(at),coalesce(bool_or(unknown),false) into n,last_attempt,unknown_attempt from (
  select r.dial_claimed_at at,(r.call_sid is null and r.call_ended_at is null) unknown
  from public.icash_call_recordings r
  where r.party='seller' and r.to_phone=p.phone and r.voice_job_id is distinct from p_job and r.dial_claimed_at is not null
   and (r.dial_claimed_at>now()-interval '24 hours' or (r.call_sid is null and r.call_ended_at is null))
  union all
  select c.created_at,false from public.icash_customer_phone_calls c
  where c.recipient_phone=p.phone and c.child_sid is not null and c.created_at>now()-interval '24 hours'
 ) attempts;
 if unknown_attempt then return false;end if;
 if j.seller_followup_of is not null then
  return n=1 and last_attempt<=clock_timestamp()-interval '2 hours'
   and public.icash_unanswered_seller_call_current(p_account,j.seller_followup_of,p_job);
 end if;
 -- Real active conversations, due requested callbacks and validated notices
 -- retain the existing receipt-bound service path. A job flag is not proof.
 if coalesce(public.icash_voice_outreach_context(p_account,p_job)->>'activeConversation','false')='true'
  or public.icash_requested_seller_call_current(p_account,p_job) then return true;end if;
 -- A completed address response followed by a ready cash offer is existing
 -- seller work. Bind it to the original lead, permission, phone and actual call.
 if j.meta_offer_lead_id is not null and exists(
  select 1 from public.icash_meta_leads m
  join public.icash_seller_intakes l on l.id=m.lead_id and l.phone=p.phone
  join public.icash_contact_permissions cp on cp.id=j.permission_id and cp.account_id=m.account_id
   and cp.seller_intake_id=m.lead_id and cp.screening_id=m.screening_id and cp.phone=l.phone
  join public.icash_call_recordings first_call on first_call.voice_job_id=m.voice_job_id
   and first_call.account_id=m.account_id and first_call.to_phone=l.phone and first_call.call_sid is not null
  where m.lead_id=j.meta_offer_lead_id and m.account_id=p_account and m.screening_id=p.screening_id
   and m.address_confirmed_at>=first_call.dial_claimed_at and m.address_confirmed_at<=now()
   and m.offer_ready_at>=m.address_confirmed_at and m.offer_ready_at<=now()
   and m.offer_authorized_at is null and not m.paused and not m.voice_paused and m.declined_at is null
   and cp.revoked_at is null and cp.permission_until>now()
 ) then return true;end if;
 if j.meta_followup_lead_id is not null then
  return n<2 and (last_attempt is null or last_attempt<=now()-interval '2 hours')
   and public.icash_meta_followup_call_current(j.meta_followup_lead_id,p_job);
 end if;
 -- Owner self-demonstrations require their own fresh form receipt even when
 -- the rolling-day window clears. Expired requests cannot dial tomorrow.
 if p_account='48dfb798-8c1a-404f-88c0-c396cc067062'::uuid and p.phone='+12142185280'
  and exists(select 1 from public.icash_contact_permissions cp
   join public.icash_seller_intakes l on l.id=cp.seller_intake_id
   where cp.id=j.permission_id and cp.account_id=p_account and l.contact_consent_scope='icash_x_demo') then
  return public.icash_owner_demo_call_current(p_account,p_job);
 end if;
 -- One new automatic introduction per phone per rolling day. Other properties
 -- do not create permission to call the same person again immediately.
 return n=0;
end $function$

CREATE OR REPLACE FUNCTION public.icash_seller_response_disposition(p_body text)
 RETURNS text
