begin
 if public.icash_seller_direct_response_match(b,$pattern$\y(?:do not|don't|dont) send (?:me|us) (?:any |more |any more )?(?:texts?|messages?|emails?)(?: again)?\y|(?:^|[.!?;] +)(?:please )?stop(?: please)?[.! ,]*$|\y(?:stop|quit) (?:asking|bothering|harassing) (?:me|us)\y|\yplease unsubscribe(?: me)?\y|(?:^|[,;.!] +)(?:please )?(?:unsubscribe|dnc)(?: me)?[.! ,]*$|^(?:please )?(?:stop|stopall|unsubscribe|cancel|end|quit|revoke|opt out|dnc)(?: please)?(?:[.! ,]*$|\s*[,;.!]\s*(?:please\y|call\y|text\y|but\y))|\y(?:(?:do not|don't|dont) want (?:you|your (?:company|business)) to (?:ever )?(?:call|text|email|contact)\y|(?:do not|don't|dont|never) (?:ever )?(?:call|text|email|message|contact)(?:ing)?(?: (?:me|us))?\y(?! (?:it|that|the house|the property)\y)|(?:stop|quit) (?:(?:calling|texting|emailing|messaging|contacting)\y|(?:call|text|email|message|contact)\y(?! (?:it|that|the house|the property)\y))|(?:unsubscribe|remove|delete) (?:me|us|(?:my|our|this) (?:phone )?number)\y|take (?:me|us|(?:my|our|this) (?:phone )?number) off\y|leave (?:me|us) alone\y|(?:put|add|place) (?:me|us|(?:my|our|this) (?:phone )?number) (?:on|in) (?:your |the )?(?:dnc|do not call)(?: list)?\y|(?:i am|i'm) (?:already )?on (?:the |your )?(?:dnc|do not call) list\y)$pattern$) then return 'opt_out';end if;
 if public.icash_seller_direct_response_match(b,$pattern$(?:^|[.!?;] +)(?:please )?stop[.!;](?: +|$)$pattern$) then return 'opt_out';end if;
 if public.icash_seller_direct_response_match(b,$pattern$(?:^|[.!?;] +)(?:(?:ok(?:ay)?|yes)[, ]+)?(?:never mind|nevermind|forget it|go away|go to hell)(?: please)?[.! ,]*$$pattern$) then return 'declined';end if;
 decline_body:=case when b ~ '\y(call|talk)\y' then regexp_replace(b,$pattern$\ynot (?:(?:super|very|really|that|at all) )?interested in (?:texting|emailing|emails|texts)\y$pattern$,'','g') else b end;
 if public.icash_seller_direct_response_match(decline_body,$pattern$\y(?:i|we)(?:'ve)? (?:(?:have|already) ){0,2}told (?:you|yall|y'all|you all) no\y|\y(?:i|we) (?:will not|won't|wont) (?:ever )?sell\y|\y(?:no thanks|no thank you|wrong (?:phone )?number|not (?:up )?for sale|(?:i am|i'm|we are|we're) not (?:the )?owner|(?:i|we) (?:do not|don't|dont) own (?:the |this |that |my |our )?(?:house|home|property)|not (?:(?:super|very|really|that|at all) )?interested|(?:do not|don't|dont) want to sell|not selling(?: (?:my|our|the) (?:house|home|property))?|no quiero vender|no me interesa vender)\y$pattern$) then
  return case when b ~ '\y(unless|if|but)\y|[$]|\yprice\y' then 'review' else 'declined' end;
 end if;
 if public.icash_seller_direct_response_match(b,$pattern$\y(?:tired|sick) of (?:these|your|the) (?:texts|messages|calls)\y|\y(?:scam|scammer|scammers|fraud|fraudulent|suspicious|(?:i am|i'm|we are|we're) not (?:comfortable|ready)|need to think|never agreed|hold off|not for me|no interest|not looking to sell|(?:do not|don't|dont) trust|not now|not sure (?:about|i want)|stop bothering|waste of (?:my )?time)\y|^(?:not comfortable|not ready)[.! ,]*$$pattern$) then
  if strpos(b,'?')=0 and b ~ $pattern$\y(?:not|isn't|is not|wasn't|was not) (?:a )?(?:scam|fraud)\y$pattern$
   and not public.icash_seller_direct_response_match(b,$pattern$\y(?:tired|sick) of (?:these|your|the) (?:texts|messages|calls)\y|\y(?:suspicious|(?:i am|i'm|we are|we're) not (?:comfortable|ready)|need to think|never agreed|hold off|not for me|no interest|not looking to sell|(?:do not|don't|dont) trust|not now|not sure (?:about|i want)|stop bothering|waste of (?:my )?time)\y|^(?:not comfortable|not ready)[.! ,]*$$pattern$) then return null;end if;
  return 'review';
 end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION public.icash_seller_response_operation_allowed(p_account uuid, p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare scope record;
begin
 if p_operation like 'voice:%' then
  select p.phone,p.contact_key,p.screening_id,j.permission_id,j.cancellation_notice_id into scope
  from public.icash_voice_jobs j join public.icash_voice_contact_targets p on p.id=coalesce(j.permission_id,j.operational_contact_id) and p.account_id=j.account_id
  where j.account_id=p_account and 'voice:'||j.id=p_operation and p.party='seller';
  if not found then return true;end if;
  if exists(select 1 from public.icash_text_suppressions where phone=scope.phone) or exists(select 1 from public.icash_contact_suppressions where contact_key=scope.contact_key) then return false;end if;
  -- Explicit channel choices survive network-pool assignments, unlike soft
  -- conversation holds. Read the canonical lead through the bound permission.
  if exists(select 1 from public.icash_contact_permissions p join public.icash_meta_leads m on m.lead_id=p.seller_intake_id
   where p.id=scope.permission_id and p.account_id=p_account and m.voice_paused) then return false;end if;
  if scope.cancellation_notice_id is not null then return true;end if;
  return not exists(select 1 from public.icash_screening_jobs s join public.icash_property_controls c on c.account_id=s.account_id and c.property_id=s.snapshot->>'propertyId'
    where s.account_id=p_account and s.id=scope.screening_id and c.manual)
   and not exists(select 1 from public.icash_meta_leads m where m.account_id=p_account and m.screening_id=scope.screening_id and (m.paused or m.declined_at is not null));
 elsif p_operation like 'text:%' or p_operation like 'sms-ai:%' then
  select t.recipient phone,t.paused,d.screening_id,m.customer_author_id into scope from public.icash_text_threads t join public.icash_deal_files d on d.id=t.deal_id and d.account_id=t.account_id
  left join public.icash_text_messages m on m.thread_id=t.id and m.account_id=t.account_id and 'text:'||m.id=p_operation
  left join public.icash_text_ai_jobs j on j.thread_id=t.id and j.account_id=t.account_id and 'sms-ai:'||j.id=p_operation
  where t.account_id=p_account and t.party='seller' and (m.id is not null or j.id is not null);
  if not found then return true;end if;
  if exists(select 1 from public.icash_text_suppressions where phone=scope.phone) or exists(select 1 from public.icash_contact_suppressions where contact_key=encode(sha256(convert_to(scope.phone,'UTF8')),'hex')) then return false;end if;
  if scope.customer_author_id is not null then return true;end if;
  return not scope.paused and not exists(select 1 from public.icash_screening_jobs s join public.icash_property_controls c on c.account_id=s.account_id and c.property_id=s.snapshot->>'propertyId'
    where s.account_id=p_account and s.id=scope.screening_id and c.manual);
 elsif p_operation like 'deal-email:%' then
  select m.id,m.recipient,d.screening_id,o.email_id into scope from public.icash_deal_emails m join public.icash_deal_files d on d.id=m.deal_id and d.account_id=m.account_id
   left join public.icash_seller_email_openers o on o.email_id=m.id and o.account_id=m.account_id
   where m.account_id=p_account and 'deal-email:'||m.id=p_operation;
  if not found then return true;end if;
  if exists(select 1 from public.icash_email_suppressions e where e.account_id=p_account and e.email=lower(scope.recipient)) then return false;end if;
  -- Honor historical phone opt-outs even when they predate the email bridge.
  if exists(select 1 from public.icash_seller_matches sm join public.icash_seller_intakes l on l.id=sm.lead_id
   where sm.account_id=p_account and sm.screening_id=scope.screening_id and lower(l.email)=lower(scope.recipient)
    and (exists(select 1 from public.icash_text_suppressions x where x.phone=l.phone)
     or exists(select 1 from public.icash_contact_suppressions x where x.contact_key=encode(sha256(convert_to(l.phone,'UTF8')),'hex')))) then return false;end if;
  if scope.email_id is null then return true;end if;
  return not exists(select 1 from public.icash_screening_jobs s join public.icash_property_controls c on c.account_id=s.account_id and c.property_id=s.snapshot->>'propertyId'
    where s.account_id=p_account and s.id=scope.screening_id and c.manual);
 end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_seller_text_operation_current(p_account uuid, p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare m public.icash_text_messages;t public.icash_text_threads;followup boolean;
begin
 if left(p_operation,5)<>'text:' then return true;end if;
 perform 1 from public.icash_operating_budget where id=1 for update;
 if p_operation !~ '^text:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return false;end if;
 select * into m from public.icash_text_messages where id=substring(p_operation from 6)::uuid and account_id=p_account;
 if not found then return false;end if;
 select * into t from public.icash_text_threads where id=m.thread_id and account_id=p_account;
 if not found then return false;end if;
 perform pg_advisory_xact_lock(hashtextextended(t.recipient,74));
 followup:=exists(select 1 from public.icash_seller_gaps g where g.account_id=p_account and g.thread_id=t.id and g.outgoing_id=m.id and g.reason='no_response');
 return public.icash_seller_text_cadence_current(p_account,t.id,m.id,followup);
end $function$

CREATE OR REPLACE FUNCTION public.icash_voice_outreach_hours_current(p_account uuid, p_job uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare context jsonb;
begin
 context:=public.icash_voice_outreach_context(p_account,p_job);
 if context is null then return false;end if;
 return public.icash_owner_demo_call_current(p_account,p_job)
  or public.icash_outreach_window_open(context->>'timezone',null,clock_timestamp());
end $function$

CREATE OR REPLACE FUNCTION public.icash_outreach_window_open(p_timezone text, p_basis text DEFAULT NULL::text, p_clock timestamp with time zone DEFAULT now())
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare zone text;local_hour numeric;
begin
 if isfinite(p_clock) is distinct from true then return false;end if;
 zone:=public.icash_outreach_timezone(p_timezone,p_basis);
 if zone is null then return false;end if;
 local_hour:=extract(hour from p_clock at time zone zone);
 return local_hour>=9 and local_hour<21;
end $function$
